import java.util.Scanner;

public class WaterTax {
    private int consumerNo;
    private String consumerName;
    private int gallons;
    private double tax;

    public WaterTax() {
        consumerNo = 0;
        consumerName = "";
        gallons = 0;
        tax = 0.0;
    }

    public void input() {
        Scanner in = new Scanner(System.in);
        System.out.print("Enter Consumer Number: ");
        consumerNo = in.nextInt();
        in.nextLine();
        System.out.print("Enter Consumer Name: ");
        consumerName = in.nextLine();
        System.out.print("Enter Gallons Consumed: ");
        gallons = in.nextInt();
    }

    public void calculate() {
        double usageTax = 0.0;
        if (gallons <= 100) {
            usageTax = 0.0;
        } else if (gallons <= 300) {
            usageTax = (gallons - 100) * 2.00;
        } else if (gallons <= 600) {
            usageTax = (200 * 2.00) + (gallons - 300) * 3.50;
        } else {
            usageTax = (200 * 2.00) + (300 * 3.50) + (gallons - 600) * 5.00;
        }
        tax = 100.0 + usageTax; // Maintenance charge Rs 100
    }

    public void display() {
        System.out.println("\n============== WATER TAX BILL ==============");
        System.out.println("Consumer Number  : " + consumerNo);
        System.out.println("Consumer Name    : " + consumerName);
        System.out.println("Gallons Consumed : " + gallons);
        System.out.println("Total Water Tax  : Rs. " + tax);
        System.out.println("============================================");
    }

    public static void main(String[] args) {
        WaterTax bill = new WaterTax();
        bill.input();
        bill.calculate();
        bill.display();
    }
}
```

