import java.util.Scanner;

public class BinarySearchInsertPosition {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        final int N = 10;
        int[] arr = new int[N];

        System.out.println("Enter " + N + " sorted integers:");
        for (int i = 0; i < N; i++) arr[i] = sc.nextInt();

        System.out.print("Enter search key: ");
        int key = sc.nextInt();

        int low = 0, high = N - 1;
        int foundIdx = -1;

        while (low <= high) {
            int mid = low + (high - low) / 2;
            if (arr[mid] == key) {
                foundIdx = mid;
                break;
            } else if (arr[mid] < key) {
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }

        System.out.println();
        if (foundIdx != -1) {
            System.out.println("Element " + key + " FOUND at position " + (foundIdx + 1) + ".");
        } else {
            System.out.println("Element " + key + " NOT FOUND.");
            System.out.println("It should be inserted at index " + low + " to preserve sorted order.");
        }
    }
}
```

