import java.util.Scanner;

public class GeneralizedArmstrongCheck {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        System.out.print("Enter a positive integer: ");
        int num = sc.nextInt();

        if (num <= 0) {
            System.out.println("Please enter a positive integer.");
            return;
        }

        int temp = num;
        int nDigits = 0;
        while (temp > 0) {
            nDigits++;
            temp /= 10;
        }

        temp = num;
        double sum = 0.0;
        while (temp > 0) {
            int d = temp % 10;
            sum += Math.pow(d, nDigits);
            temp /= 10;
        }

        System.out.println("\nNumber of digits = " + nDigits);
        System.out.println("Power sum        = " + (int) sum);

        if ((int) sum == num) {
            System.out.println(num + " is an ARMSTRONG NUMBER.");
        } else {
            System.out.println(num + " is NOT an Armstrong Number.");
        }
    }
}
```

