import java.util.Scanner;

public class MatrixSaddlePoint {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        System.out.print("Enter square matrix order N (3 to 6): ");
        int n = in.nextInt();

        int[][] mat = new int[n][n];
        System.out.println("Enter " + (n * n) + " elements:");
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                mat[i][j] = in.nextInt();
            }
        }

        boolean found = false;

        for (int i = 0; i < n; i++) {
            // Find minimum in row i
            int minVal = mat[i][0];
            int colIdx = 0;
            for (int j = 1; j < n; j++) {
                if (mat[i][j] < minVal) {
                    minVal = mat[i][j];
                    colIdx = j;
                }
            }

            // Check if minVal is the maximum in its column colIdx
            boolean isMaxInCol = true;
            for (int k = 0; k < n; k++) {
                if (mat[k][colIdx] > minVal) {
                    isMaxInCol = false;
                    break;
                }
            }

            if (isMaxInCol) {
                System.out.println("\nSaddle Point Found = " + minVal + " at Row " + i + ", Column " + colIdx);
                found = true;
                break;
            }
        }

        if (!found) {
            System.out.println("\nNo Saddle Point exists in the matrix.");
        }
    }
}
```

