import java.util.Scanner;

public class MenuPerfectPascal {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        System.out.println("========== UTILITY MENU ==========");
        System.out.println("1. Perfect Number Check");
        System.out.println("2. Generate Pascal's Triangle");
        System.out.print("Enter choice (1 or 2): ");
        int choice = sc.nextInt();

        switch (choice) {
            case 1:
                System.out.print("Enter positive integer: ");
                int num = sc.nextInt();
                int divisorSum = 0;
                for (int i = 1; i <= num / 2; i++) {
                    if (num % i == 0) divisorSum += i;
                }
                if (divisorSum == num && num > 0) {
                    System.out.println(num + " is a PERFECT NUMBER.");
                } else {
                    System.out.println(num + " is NOT a Perfect Number (Divisor sum = " + divisorSum + ").");
                }
                break;

            case 2:
                System.out.print("Enter number of rows (1 to 10): ");
                int rows = sc.nextInt();
                System.out.println("\nPascal's Triangle (" + rows + " rows):");
                for (int i = 0; i < rows; i++) {
                    int val = 1;
                    for (int s = 0; s < rows - 1 - i; s++) System.out.print("  ");
                    for (int j = 0; j <= i; j++) {
                        System.out.printf("%4d", val);
                        val = val * (i - j) / (j + 1);
                    }
                    System.out.println();
                }
                break;

            default:
                System.out.println("Invalid Selection.");
        }
    }
}
```

